package com.acme.transit.sales;

/**
 * Blocks ticket issuance when the departure's seat allocation is exhausted.
 */
public class DepartureSeatGuard {

    private final SeatAllocationRepository allocations;

    public DepartureSeatGuard(SeatAllocationRepository allocations) {
        this.allocations = allocations;
    }

    public void assertSeatAvailable(String departureId, String seatClass, int requested) {
        int remaining = allocations.remaining(departureId, seatClass);
        if (remaining < requested) {
            throw new SoldOutException(departureId, seatClass, remaining, requested);
        }
    }
}

class SoldOutException extends RuntimeException {
    public SoldOutException(String departure, String cls, int remaining, int requested) {
        super("Only " + remaining + " seats in " + cls + " for " + departure + " (requested " + requested + ")");
    }
}

