package com.acme.transit.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Computes ticket fare from base, class supplement, booking fee and concession.
 */
public class FareCalculator {

    private final FareTable fares;
    private final BookingFeePolicy fees;
    private final ConcessionPolicy concessions;

    public FareCalculator(FareTable fares, BookingFeePolicy fees, ConcessionPolicy concessions) {
        this.fares = fares;
        this.fees = fees;
        this.concessions = concessions;
    }

    public BigDecimal fare(String routeId, String seatClass, String fareClass, String passengerId) {
        BigDecimal base = fares.baseFare(routeId);
        BigDecimal supplement = fares.classSupplement(seatClass);
        BigDecimal fee = fees.forChannel("ONLINE");
        BigDecimal subtotal = base.add(supplement).add(fee);
        if ("CONCESSION".equals(fareClass)) {
            subtotal = concessions.apply(subtotal, passengerId);
        }
        return subtotal.setScale(2, RoundingMode.HALF_UP);
    }
}

