package com.acme.transit.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Ticket purchase endpoint: seat check, charge, issue ticket.
 */
@RestController
public class TicketPurchaseController {

    private final DepartureSeatGuard seats;
    private final FareCalculator fares;
    private final PaymentProcessor payments;
    private final TicketIssuer issuer;

    public TicketPurchaseController(DepartureSeatGuard seats, FareCalculator fares, PaymentProcessor payments, TicketIssuer issuer) {
        this.seats = seats;
        this.fares = fares;
        this.payments = payments;
        this.issuer = issuer;
    }

    @PostMapping("/tickets")
    public TicketView purchase(@RequestBody TicketPurchaseRequest req) {
        seats.assertSeatAvailable(req.getDepartureId(), req.getSeatClass(), req.getPassengers().size());
        var amount = fares.fare(req.getRouteId(), req.getSeatClass(), req.getFareClass(), req.getPassengerId());
        payments.charge(req.getPaymentMethod(), amount);
        IssuedTicket ticket = issuer.issue(req, amount);
        return new TicketView(ticket.getReference(), ticket.getQrCode(), amount);
    }
}

