package com.acme.transit.access;

import java.time.Instant;

/**
 * Validates a ticket QR at the gate, opens the barrier, records usage.
 */
public class GateValidationService {

    private final TicketRepository tickets;
    private final GateGateway gate;

    public GateValidationService(TicketRepository tickets, GateGateway gate) {
        this.tickets = tickets;
        this.gate = gate;
    }

    public void validate(String ticketReference, String gateId) {
        Ticket t = tickets.require(ticketReference);
        if (t.isCancelled() || t.isUsed()) {
            throw new InvalidTicketException(ticketReference, "already used or cancelled");
        }
        if (!t.getDepartureId().equals(gate.departureFor(gateId))) {
            throw new InvalidTicketException(ticketReference, "ticket not valid at this gate");
        }
        gate.open(gateId);
        t.markUsed(Instant.now(), gateId);
        tickets.save(t);
    }
}

