package com.acme.transit.operator;

import java.time.Instant;

/**
 * Opens and closes ticket sales for a departure.
 */
public class SalesWindowService {

    private final DepartureRepository departures;

    public SalesWindowService(DepartureRepository departures) {
        this.departures = departures;
    }

    public void openSales(String departureId, Instant cutoff) {
        Departure d = departures.require(departureId);
        if (d.getSalesState() != SalesState.CLOSED) {
            throw new IllegalStateException("Departure is not closed");
        }
        d.setSalesState(SalesState.OPEN);
        d.setSalesCutoff(cutoff);
        departures.save(d);
    }

    public void closeSales(String departureId) {
        Departure d = departures.require(departureId);
        d.setSalesState(SalesState.CLOSED);
        departures.save(d);
    }
}

