package com.acme.transit.rules;

import java.time.Duration;
import java.time.Instant;

/**
 * Determines whether a ticket is eligible for refund under fare rules.
 */
public class RefundEligibilityRule {

    private static final Duration MIN_NOTICE = Duration.ofHours(2);

    public boolean isEligible(Ticket ticket, Instant now) {
        if (!ticket.getFareRules().isRefundable()) {
            return false;
        }
        if (ticket.isUsed() || ticket.isCancelled()) {
            return false;
        }
        return now.plus(MIN_NOTICE).isBefore(ticket.getDepartureAt());
    }

    public void assertEligible(Ticket ticket, Instant now) {
        if (!isEligible(ticket, now)) {
            throw new RefundNotPermittedException(ticket.getReference());
        }
    }
}

class RefundNotPermittedException extends RuntimeException {
    public RefundNotPermittedException(String reference) {
        super("Ticket " + reference + " is not refundable");
    }
}

