package com.acme.transit.audit;

import java.math.BigDecimal;
import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an immutable audit row for each ticket lifecycle event.
 */
public class TicketEventAuditor {

    private final EntityManager em;

    public TicketEventAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String passengerId, String ticketReference, String eventType, BigDecimal amount) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            TicketEventEntry e = new TicketEventEntry();
            e.setPassengerId(passengerId);
            e.setTicketReference(ticketReference);
            e.setEventType(eventType);
            e.setAmount(amount);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

