package com.acme.transit.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises counter-side ticket cancellation by the issuing agent.
 */
public class CounterCancellationPolicy {

    private final TicketRepository tickets;
    private final StaffDirectory staff;

    public CounterCancellationPolicy(TicketRepository tickets, StaffDirectory staff) {
        this.tickets = tickets;
        this.staff = staff;
    }

    public void assertMayCancel(String userId, String ticketReference) {
        Ticket t = tickets.require(ticketReference);
        if (!staff.hasRole(userId, "AGENT")) {
            throw new AccessDeniedException("Cancellation at counter requires AGENT role");
        }
        if (t.getIssuingAgentId() != null && !t.getIssuingAgentId().equals(userId)) {
            throw new AccessDeniedException("Only the issuing agent may cancel this ticket");
        }
    }
}

