#include <stdio.h>
#include "transit_db.h"

int write_route_reconciliation(const char *day, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "route_id,issued,used,fares_collected,refunds_paid\n");

    db_cursor_t *cur = NULL;
    if (db_open_route_daily_cursor(&cur, day) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    route_daily_row_t row;
    while (db_route_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%d,%d,%.2f,%.2f\n",
                row.route_id, row.issued, row.used, row.fares_collected, row.refunds_paid);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

